mapper.select:
SELECT id, title, type, file_key, is_downloadable, status, ingestion_status, ingestion_error, ingestion_revision, ingested_at, course_id, created_at, updated_at
FROM edu.materials
WHERE id = #{id}

SELECT id, title, type, file_key, is_downloadable, status, ingestion_status, ingestion_error, ingestion_revision, ingested_at, course_id, created_at, updated_at
FROM edu.materials
WHERE id = #{id}
  AND course_id = #{courseId}

SELECT id, title, type, file_key, is_downloadable, status, ingestion_status, ingestion_error, ingestion_revision, ingested_at, course_id, created_at, updated_at
FROM edu.materials
WHERE file_key = #{fileKey}

SELECT id, title, type, file_key, is_downloadable, status, ingestion_status, ingestion_error, ingestion_revision, ingested_at, course_id, created_at, updated_at
FROM edu.materials
WHERE course_id = #{courseId}

SELECT m.id, m.title, m.type, m.file_key, m.is_downloadable, m.status, m.ingestion_status, m.ingestion_error, m.ingestion_revision, m.ingested_at, m.course_id, m.created_at, m.updated_at
FROM edu.materials m
INNER JOIN edu.chapter_materials cm ON m.id = cm.material_id
WHERE cm.chapter_id = #{chapterId}
  AND m.course_id = #{courseId}
